import {normalizeSearch, searchTokens} from '@crew/shared';

function normalizedOffsets(source) {
  const segmenter = new Intl.Segmenter('en', {granularity: 'grapheme'});
  let normalized = '';
  const starts = [], ends = [], boundaries = [0];
  for (const {segment, index} of segmenter.segment(source)) {
    const value = normalizeSearch(segment);
    normalized += value;
    for (let offset = 0; offset < value.length; offset++) {
      starts.push(index);
      ends.push(index + segment.length);
    }
    boundaries.push(index + segment.length);
  }
  return {normalized, starts, ends, boundaries};
}

function matchRanges(source, terms) {
  const {normalized, starts, ends, boundaries} = normalizedOffsets(source);
  const needles = [...new Set(terms.flatMap(term => term.quoted ? [normalizeSearch(term.value)] : searchTokens(term.value)).filter(Boolean))];
  const ranges = [];
  for (const needle of needles) {
    let index = normalized.indexOf(needle);
    while (index >= 0) {
      ranges.push([starts[index], ends[index + needle.length - 1]]);
      index = normalized.indexOf(needle, index + Math.max(needle.length, 1));
    }
  }
  ranges.sort((left, right) => left[0] - right[0] || right[1] - left[1]);
  const merged = [];
  for (const range of ranges) {
    const previous = merged.at(-1);
    if (previous && range[0] <= previous[1]) previous[1] = Math.max(previous[1], range[1]);
    else merged.push([...range]);
  }
  return {ranges: merged, boundaries};
}

export function highlightSegments(value, terms, {maximum = 320, context = 70} = {}) {
  const source = String(value ?? '');
  if (!source) return [];
  const {ranges, boundaries} = matchRanges(source, terms);
  const first = ranges[0]?.[0] ?? 0;
  const desiredStart = Math.max(0, first - context);
  const start = boundaries.find(boundary => boundary >= desiredStart) ?? source.length;
  const desiredEnd = Math.min(source.length, start + maximum);
  const end = boundaries.find(boundary => boundary >= desiredEnd) ?? source.length;
  const segments = start ? [{text: '…', match: false}] : [];
  let position = start;
  for (const [from, to] of ranges) {
    if (to <= start || from >= end) continue;
    const clippedFrom = Math.max(start, from), clippedTo = Math.min(end, to);
    if (clippedFrom > position) segments.push({text: source.slice(position, clippedFrom), match: false});
    segments.push({text: source.slice(clippedFrom, clippedTo), match: true});
    position = clippedTo;
  }
  if (position < end) segments.push({text: source.slice(position, end), match: false});
  if (end < source.length) segments.push({text: '…', match: false});
  return segments;
}

import {searchTokens} from '@crew/shared';

function intersection(left, right) {
  const [smaller, larger] = left.size <= right.size ? [left, right] : [right, left];
  return new Set([...smaller].filter(id => larger.has(id)));
}

function union(left, right) {
  return new Set([...left, ...right]);
}

export function authorizedDocuments(ctx, access) {
  const select = ctx.db.prepare('SELECT issue_id,project_id,comments_text FROM search_documents WHERE org_id=? AND project_id=? ORDER BY issue_id');
  return access.projectIds.flatMap(projectId => select.all(access.orgId, projectId));
}

export function planCandidates(ctx, access, ast, documents) {
  const universe = new Set(documents.map(document => document.issue_id));
  const cache = new Map();
  const lookup = ctx.db.prepare(`SELECT DISTINCT t.issue_id FROM search_terms t
    JOIN search_documents d ON d.issue_id=t.issue_id
    WHERE d.org_id=? AND d.project_id=? AND t.token>=? AND t.token<?`);
  function prefixIds(prefix) {
    if (cache.has(prefix)) return cache.get(prefix);
    const matches = new Set();
    for (const projectId of access.projectIds) {
      const rows = lookup.all(access.orgId, projectId, prefix, prefix + '\u{10ffff}');
      for (const row of rows) matches.add(row.issue_id);
    }
    cache.set(prefix, matches);
    return matches;
  }
  function candidates(node) {
    if (node.type === 'term') {
      const tokens = searchTokens(node.value);
      if (!tokens.length) return universe;
      let matches = null;
      for (const token of tokens) {
        matches = matches === null ? prefixIds(token) : intersection(matches, prefixIds(token));
        if (!matches.size) break;
      }
      return matches ?? universe;
    }
    if (node.type === 'and') return intersection(candidates(node.left), candidates(node.right));
    if (node.type === 'or') return union(candidates(node.left), candidates(node.right));
    return universe;
  }
  return candidates(ast);
}

import {createHash} from 'node:crypto';
import {AppError, text, validatedQuery, evaluateQuery, positiveTerms, queryFilters, matchesText} from '@crew/shared';
import {encodeCursor} from '../../http/pagination.js';
import {getIssue} from '../work/issues.js';
import {documentFields, prefixScores} from './search-index.js';
import {highlightSegments} from './highlights.js';
import {authorizedDocuments, planCandidates} from './search-plan.js';

export function searchAccess(ctx, req, query = req.query) {
  ctx.permissions.scope(req, 'insight:read');
  const orgId = text(query.orgId, 'orgId', {max: 100});
  if (!ctx.permissions.membership(req.user.id, orgId)) throw new AppError('FORBIDDEN', 'Organization permission denied', 403);
  let projects = ctx.permissions.projectIds(req.user.id, orgId).filter(id => ctx.permissions.canProject(req.user.id, id, 'insight:read'));
  if (query.projectId) {
    const project = ctx.permissions.assertProject(req, query.projectId, 'insight:read');
    if (project.org_id !== orgId) throw new AppError('VALIDATION', 'Project must belong to this organization', 422, {projectId: 'Choose a project in this organization'});
    projects = projects.filter(id => id === project.id);
  }
  return {orgId, projectIds: projects};
}

export function validateQueryProjects(ctx, ast, orgId, projectIds) {
  const accessible = new Set(projectIds);
  for (const filter of queryFilters(ast).filter(node => node.field === 'project')) {
    const project = ctx.db.prepare('SELECT id FROM projects WHERE org_id=? AND (id=? OR key=? COLLATE NOCASE)').get(orgId, filter.value, filter.value);
    if (!project || !accessible.has(project.id)) throw new AppError('FORBIDDEN', 'The query refers to an unavailable project', 403);
  }
}

export {highlightSegments} from './highlights.js';

function facets(items, property) {
  const counts = new Map();
  for (const item of items) {
    const value = item[property] ?? 'unassigned';
    counts.set(value, (counts.get(value) ?? 0) + 1);
  }
  return [...counts].map(([value, count]) => ({value, count})).sort((a, b) => b.count - a.count || String(a.value).localeCompare(String(b.value)));
}

export function searchIssues(ctx, req, query = req.query) {
  const access = searchAccess(ctx, req, query);
  const {query: source, ast} = validatedQuery(query.q ?? query.query ?? '');
  validateQueryProjects(ctx, ast, access.orgId, access.projectIds);
  const terms = positiveTerms(ast);
  const documents = authorizedDocuments(ctx, access);
  const candidates = planCandidates(ctx, access, ast, documents);
  const now = Date.parse(ctx.now());
  const results = [];
  for (const document of documents) {
    if (!candidates.has(document.issue_id)) continue;
    const issue = getIssue(ctx, document.issue_id);
    const searchable = {...issue, searchComments: document.comments_text};
    if (!evaluateQuery(ast, searchable, {userId: req.user.id})) continue;
    const fields = documentFields(issue, document.comments_text);
    const ageDays = Math.max(0, (now - Date.parse(issue.updatedAt)) / 86400000);
    const recency = 1 / (1 + ageDays / 30);
    let score = prefixScores(ctx, issue.id, terms) + recency;
    for (const term of terms.filter(item => item.quoted)) {
      if (matchesText(issue.title, term)) score += 20;
    }
    const matchFields = Object.entries(fields).filter(([, value]) => terms.some(term => matchesText(value, term))).map(([field]) => field);
    results.push({...issue, score: Number(score.toFixed(6)), matchFields, highlights: {
      title: highlightSegments(issue.title, terms, {maximum: 500}),
      description: highlightSegments(issue.description, terms),
      comments: highlightSegments(document.comments_text, terms)
    }});
  }
  results.sort((a, b) => b.score - a.score || b.updatedAt.localeCompare(a.updatedAt) || a.id.localeCompare(b.id));
  const {limit, cursor} = ctx.pagination(query);
  const fingerprint = createHash('sha256').update(JSON.stringify([req.user.id, access.orgId, query.projectId ?? null, source])).digest('hex');
  let start = 0;
  if (cursor) {
    if (cursor.fingerprint !== fingerprint || typeof cursor.id !== 'string') throw new AppError('VALIDATION', 'Cursor belongs to a different search', 422, {cursor: 'Run the query from its first page'});
    const index = results.findIndex(item => item.id === cursor.id);
    start = index < 0 ? results.length : index + 1;
  }
  const items = results.slice(start, start + limit);
  return {items, total: results.length, query: source,
    facets: {status: facets(results, 'statusName'), assignee: facets(results, 'assigneeId'), priority: facets(results, 'priority')},
    nextCursor: start + limit < results.length && items.length ? encodeCursor({fingerprint, id: items.at(-1).id}) : null};
}
